package com.autojobapply.application;
import com.autojobapply.config.Config; import com.autojobapply.model.*; import com.autojobapply.tracking.ApplicationTracker;
/** Guard rail: public job feeds do not authorize form submission. An employer-authorized API adapter is required. */
public final class SubmissionService { private final Config config;private final ApplicantProfile profile;private final ApplicationTracker tracker;public SubmissionService(Config c,ApplicantProfile p,ApplicationTracker t){config=c;profile=p;tracker=t;}
 public ApplicationStatus process(ScoredJob job){String reason;if(!config.autoSubmit()){reason="Automatic submission disabled by configuration"; tracker.record(job,ApplicationStatus.BLOCKED,reason);return ApplicationStatus.BLOCKED;}if(!config.authorizedSubmission()){reason="No employer-authorized submission integration configured; public listing access is discovery-only";tracker.record(job,ApplicationStatus.UNSUPPORTED,reason);return ApplicationStatus.UNSUPPORTED;}if(profile.get("email").isBlank()||profile.get("legal.name").isBlank()){reason="Verified legal name or email is unavailable";tracker.record(job,ApplicationStatus.BLOCKED,reason);return ApplicationStatus.BLOCKED;}reason="Authorized submission adapter has not been installed for this employer";tracker.record(job,ApplicationStatus.UNSUPPORTED,reason);return ApplicationStatus.UNSUPPORTED;}}
